CREATE OR REPLACE EDITIONABLE PROCEDURE "%USER_NAME%"."SET_TBL_STATUS" (pname IN VARCHAR2, ptype IN VARCHAR2, pstatus IN VARCHAR2)
is
    vNum NUMBER;
begin
    SELECT COUNT(*)
    INTO vNum
    FROM table_status
    WHERE name = pname
        AND type = ptype;

    IF vNum = 0 THEN
        INSERT INTO table_status(name, type)
        VALUES(pName, pType);
    ELSE
        UPDATE table_status
        SET status = pStatus
        WHERE name = pname
            AND type = ptype;
    END IF;
end;
/
